// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 10_000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // Rule: ether held by c equals the sum of credited holder balances.
        (, uint256 bal) = c.Acc(actor);
        assertTrue(address(c).balance == bal, "contract ether must equal credited holder balances");
    }
}
